import React, { useState, useEffect, useRef, useCallback } from 'react';
import axios from 'axios';
// import io from 'socket.io-client';
import './App.css';

// Server URL - Use direct connection to port 3001 for backend
const SERVER_URL = 'http://localhost:3001';
// Remove the socket URL constant
// const SOCKET_URL = 'http://localhost:3001'; // Explicitly set Socket.io URL to port 3001

// Placeholder Google logo image (base64 encoded small Google logo)
const PLACEHOLDER_IMAGE = 'data:image/png;base64,';

function App() {
    const [sessionId, setSessionId] = useState(null);
    const [inputValue, setInputValue] = useState('');
    const [messages, setMessages] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [browserImage, setBrowserImage] = useState(PLACEHOLDER_IMAGE); // Set initial placeholder image
    const [previewVisible, setPreviewVisible] = useState(true);
    // Add state for status messages
    const [statusMessages, setStatusMessages] = useState([{
        type: 'info',
        text: 'Test starting...',
        time: new Date().toLocaleTimeString()
    }]);
    // Add state for streaming
    const [streaming, setStreaming] = useState(false);
    const [streamStatus, setStreamStatus] = useState('waiting');
    const eventSourceRef = useRef(null);
    const messagesEndRef = useRef(null);
    // Add state for showing technical messages
    const [showTechnicalMessages, setShowTechnicalMessages] = useState(true);
    const streamSourceRef = useRef(null);
    const sourceTimeoutsRef = useRef([]);
    const streamErrorCountRef = useRef(0);
    // Add polling interval state
    const [pollingIntervalId, setPollingIntervalId] = useState(null);
    const pollIntervalRef = useRef(3000); // Default polling interval of 3 seconds

    // Toggle display of technical messages
    const toggleTechnicalMessages = () => {
        setShowTechnicalMessages(!showTechnicalMessages);
    };

    // Helper function to add status messages with a timestamp
    const addStatusMessage = (type, text) => {
        const now = new Date();
        const timeString = now.toLocaleTimeString();
        setStatusMessages(prev => {
            // Keep only the most recent 10 messages
            const newMessages = [...prev, { type, text, time: timeString }];
            if (newMessages.length > 10) {
                return newMessages.slice(newMessages.length - 10);
            }
            return newMessages;
        });
    };

    // Helper to determine status type classes
    const getStatusType = (event) => {
        switch (event) {
            case 'error': return 'error';
            case 'thinking': return 'processing';
            case 'user-message': return 'user';
            case 'ai-response': return 'assistant';
            case 'tool-call': return 'tool';
            case 'response-complete': return 'success';
            case 'warning': return 'warning';
            case 'reconnecting': return 'reconnecting';
            default: return 'info';
        }
    };

    // Helper function to fetch messages directly from the API - memoized with useCallback
    const fetchMessagesDirectly = useCallback(() => {
        if (!sessionId) return;

        console.log('Fetching messages directly via API...');

        axios.get(`${SERVER_URL}/messages/${sessionId}?_t=${Date.now()}`)
            .then(response => {
                if (response.data.success && response.data.messages) {
                    // Get current and new messages for comparison
                    const currentMessages = messages;
                    const newMessages = response.data.messages;

                    // Check if we have any new messages at all
                    if (newMessages.length <= currentMessages.length &&
                        !isAssistantMessageUpdated(currentMessages, newMessages)) {
                        console.log('No new messages or updates');
                        return;
                    }

                    // Log what we received
                    console.log(`API returned ${newMessages.length} messages (we have ${currentMessages.length})`);

                    // Find the assistant message that's being updated (if any)
                    const lastUserMessageIndex = findLastIndex(newMessages, m => m.role === 'user');
                    const assistantMessages = newMessages.filter((m, i) =>
                        i > lastUserMessageIndex && m.role === 'assistant'
                    );

                    // Improved completion check using multiple signals
                    const hasCompleteResponse = isResponseComplete(newMessages, assistantMessages);

                    // Update messages in state
                    setMessages(newMessages);

                    // Only set loading to false if we have a complete response or tools have been called
                    const toolMessages = newMessages.filter(m => m.role === 'tool' || m.role === 'function');

                    if (hasCompleteResponse) {
                        setLoading(false);
                        addStatusMessage('success', 'Response complete');
                    } else if (toolMessages.length > 0) {
                        // If we have tool calls but no complete response yet, show an appropriate message
                        addStatusMessage('processing', `Processing tool calls (${toolMessages.length} tools used so far)`);
                    }

                    // Add status message about progress
                    if (newMessages.length > currentMessages.length) {
                        const newCount = newMessages.length - currentMessages.length;
                        addStatusMessage('info', `Received ${newCount} new message${newCount > 1 ? 's' : ''}`);
                    } else if (isAssistantMessageUpdated(currentMessages, newMessages)) {
                        addStatusMessage('info', 'Assistant response updated');
                    }
                } else {
                    addStatusMessage('warning', 'API returned no messages');
                }
            })
            .catch(err => {
                console.error('Error fetching messages:', err);
                addStatusMessage('error', `Failed to fetch messages: ${err.message}`);
            });
    }, [sessionId, messages, addStatusMessage]);

    // Improved function to check if a response is complete using multiple signals
    const isResponseComplete = (allMessages, assistantMessages) => {
        // Check 1: Do we have an explicit completion signal?
        const lastAssistant = findLastMessage(allMessages, 'assistant');
        if (lastAssistant && lastAssistant.finish_reason === 'stop') {
            console.log('Response complete: finish_reason is "stop"');
            return true;
        }

        // Check 2: If the assistant used tool calls, check if they've all been processed
        if (lastAssistant && lastAssistant.tool_calls && lastAssistant.tool_calls.length > 0) {
            const toolCallIds = lastAssistant.tool_calls.map(tc => tc.id);
            const toolResponses = allMessages.filter(m =>
                (m.role === 'tool' || m.role === 'function') &&
                toolCallIds.includes(m.tool_call_id)
            );

            // If we have responses for all tool calls, consider it complete
            if (toolResponses.length === toolCallIds.length) {
                console.log('Response complete: all tool calls have responses');
                return true;
            }

            // If we're still waiting on tool responses, not complete yet
            console.log(`Waiting for tool responses: ${toolResponses.length}/${toolCallIds.length} complete`);
            return false;
        }

        // Check 3: Does the assistant message look like a complete response?
        // This is a fallback if we don't have explicit signals
        const contentComplete = assistantMessages.some(m => {
            // Check if content exists and is not empty
            if (!m.content || m.content.length < 1) return false;

            // Check for reasonable length (more reliable than 20 char threshold)
            const hasSubstantialContent = m.content.length > 20;

            // Check for natural language completion signals
            const hasCompletionMarkers = !m.content.endsWith('...') &&
                !m.content.match(/^I'm (thinking|processing|working|calculating)/);

            // Check for completed sentence structure (ends with period, question mark, etc.)
            const hasCompleteSentence = !!m.content.match(/[.!?]\s*$/);

            console.log(`Content checks: length=${hasSubstantialContent}, markers=${hasCompletionMarkers}, sentence=${hasCompleteSentence}`);

            // Consider complete if it meets most criteria
            return hasSubstantialContent && (hasCompletionMarkers || hasCompleteSentence);
        });

        if (contentComplete) {
            console.log('Response complete: content appears complete');
        }

        return contentComplete;
    };

    // Helper function to check if assistant message was updated
    const isAssistantMessageUpdated = (oldMessages, newMessages) => {
        if (!oldMessages || !newMessages) return false;

        // Find last assistant message in both arrays
        const oldAssistant = findLastMessage(oldMessages, 'assistant');
        const newAssistant = findLastMessage(newMessages, 'assistant');

        if (!oldAssistant || !newAssistant) return false;

        // Check if content is different and new message is longer
        return (
            oldAssistant.content !== newAssistant.content &&
            (newAssistant.content?.length > oldAssistant.content?.length || 0)
        );
    };

    // Helper to find the last message of a specific role
    const findLastMessage = (messages, role) => {
        for (let i = messages.length - 1; i >= 0; i--) {
            if (messages[i].role === role) return messages[i];
        }
        return null;
    };

    // Helper to find the last index of a message matching a condition
    const findLastIndex = (array, predicate) => {
        for (let i = array.length - 1; i >= 0; i--) {
            if (predicate(array[i])) return i;
        }
        return -1;
    };

    // Replace Socket.io connection with polling
    useEffect(() => {
        // Start polling for updates when we have a session
        if (sessionId) {
            console.log("Setting up polling for message updates...");
            addStatusMessage('system', `Starting polling on session: ${sessionId}`);

            // Clear any existing interval
            if (pollingIntervalId) {
                clearInterval(pollingIntervalId);
            }

            // Set up a new polling interval
            const intervalId = setInterval(() => {
                // Only poll when loading or waiting for response
                if (loading) {
                    fetchMessagesDirectly();
                }
            }, pollIntervalRef.current);

            setPollingIntervalId(intervalId);

            // Also do an initial fetch
            fetchMessagesDirectly();

            // Check server health occasionally
            setTimeout(() => {
                checkServerHealth();
            }, 5000);
        }

        // Clean up on unmount or when sessionId changes
        return () => {
            if (pollingIntervalId) {
                console.log("Cleaning up polling interval");
                clearInterval(pollingIntervalId);
                setPollingIntervalId(null);
            }
        };
    }, [sessionId, fetchMessagesDirectly, loading]);

    // Add a health check function that uses direct API calls instead of Socket.io
    const checkServerHealth = async () => {
        try {
            console.log('Checking server health...');
            const response = await axios.get(`${SERVER_URL}/health?_t=${Date.now()}`, {
                timeout: 5000
            });

            if (response.data && response.data.success) {
                console.log('Server is healthy:', response.data);
                addStatusMessage('system', 'Connected to server (health check successful)');
                return true;
            } else {
                console.warn('Server health check returned unexpected response:', response.data);
                addStatusMessage('warning', 'Server health check returned unexpected response');
                return false;
            }
        } catch (err) {
            console.error('Server health check failed:', err);
            addStatusMessage('error', `Server connection error: ${err.message}`);
            return false;
        }
    };

    // Keep this version of handleSendMessage
    const handleSendMessage = async (e) => {
        e.preventDefault();

        if (!inputValue.trim()) return;
        if (!sessionId) {
            setError('Session not initialized. Please try again.');
            return;
        }

        // Add user message to state immediately
        const userMessage = { role: 'user', content: inputValue };
        setMessages([...messages, userMessage]);
        setInputValue('');
        setLoading(true);
        setError(null);

        try {
            const endpoint = `${SERVER_URL}/chat/${sessionId}`;

            console.log(`Sending message to ${endpoint}`);

            // Send the message via HTTP (no socket.io)
            const response = await axios.post(endpoint, {
                message: inputValue
            }, {
                timeout: 10000 // Shorter timeout since we're just getting an acknowledgment
            });

            // For the HTTP response, we only need to check for success
            // The actual message processing updates will come via polling
            if (response.data.success) {
                console.log('Message received by server:', response.data.status);
                addStatusMessage('info', 'Message received by server, processing started');
            } else {
                setError(`Error: ${response.data.error}`);
                setLoading(false);
            }
        } catch (err) {
            console.error('Error sending message:', err);

            // Check if this is a 404 error (session not found)
            if (err.response && err.response.status === 404) {
                setError(`Your session has expired. Creating a new session...`);
                // Clear session ID to trigger re-initialization
                setSessionId(null);
                // Wait a moment and then initialize a new session
                setTimeout(async () => {
                    try {
                        const sessionResponse = await axios.post(`${SERVER_URL}/session`);
                        if (sessionResponse.data.success) {
                            setSessionId(sessionResponse.data.sessionId);
                            setError(`Session recreated! Please send your message again.`);
                            addStatusMessage('system', `New session initialized: ${sessionResponse.data.sessionId}`);
                        } else {
                            setError(`Error: ${sessionResponse.data.error}`);
                        }
                    } catch (sessionErr) {
                        setError(`Failed to create a new session: ${sessionErr.message}`);
                    }
                }, 1000);
                return;
            }

            // Handle other errors
            setError(`Error sending message: ${err.message}`);
            setLoading(false);
        }
    };

    // Scroll to bottom of messages
    useEffect(() => {
        scrollToBottom();
    }, [messages]);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

    // Add a function to request a screenshot
    const requestScreenshot = async () => {
        try {
            console.log("Requesting screenshot...");
            setError(null);
            const endpoint = `${SERVER_URL}/screenshot`;

            // Include the sessionId in the request if available
            const params = sessionId ? { sessionId } : {};

            // Add a cache-busting parameter
            params._t = Date.now();

            const response = await axios.get(endpoint, {
                params,
                timeout: 10000 // 10 second timeout
            });

            console.log("Screenshot requested successfully");
            return response; // Return the response for async/await
        } catch (err) {
            console.error("Error requesting screenshot:", err);
            addStatusMessage('warning', `Screenshot request failed: ${err.message}`);
            // Don't set error to UI to avoid disrupting the experience
            return null;
        }
    };

    const togglePreview = () => {
        setPreviewVisible(!previewVisible);

        // If hiding preview while streaming, stop the stream
        if (!previewVisible && streaming) {
            stopStream();
        }
    };

    // Add startStream function to initialize the browser screenshot stream
    const startStream = () => {
        console.log('Starting browser screenshot stream...');
        setStreamStatus('connecting');
        addStatusMessage('info', 'Connecting to browser stream...');

        if (streamSourceRef.current) {
            console.log('Closing existing stream before starting new one');
            stopStream();
        }

        try {
            if (!sessionId) {
                console.error('Cannot start stream without a session ID');
                addStatusMessage('error', 'Cannot start stream: No session ID');
                return;
            }

            console.log(`Initializing SSE stream for session ${sessionId}`);
            const timestamp = Date.now();
            const streamUrl = `${SERVER_URL}/browser-stream/${sessionId}?_t=${timestamp}`;

            // Create a new EventSource connection
            const source = new EventSource(streamUrl);
            streamSourceRef.current = source;

            // Set up event handlers
            source.onmessage = (event) => {
                try {
                    // Check if it's a valid data URL
                    if (event.data && event.data.startsWith('data:image/')) {
                        setBrowserImage(event.data);
                        setStreamStatus('active');

                        // Reset error count on successful message
                        streamErrorCountRef.current = 0;
                    }
                } catch (error) {
                    console.error('Error processing stream data:', error);
                    streamErrorCountRef.current++;

                    if (streamErrorCountRef.current > 5) {
                        addStatusMessage('warning', 'Multiple stream errors, connection may be unstable');
                    }
                }
            };

            // Handle status events
            source.addEventListener('status', (event) => {
                try {
                    const data = JSON.parse(event.data);
                    console.log('Stream status event:', data);

                    if (data.type === 'connected') {
                        setStreamStatus('active');
                        addStatusMessage('success', 'Browser stream connected');
                    } else if (data.type === 'warning') {
                        setStreamStatus('warning');
                        addStatusMessage('warning', data.message || 'Stream warning');
                    } else if (data.type === 'error') {
                        streamErrorCountRef.current++;
                        addStatusMessage('error', data.message || 'Stream error');
                    }
                } catch (error) {
                    console.error('Error handling status event:', error);
                }
            });

            // Handle errors
            source.onerror = (error) => {
                console.error('Stream error:', error);
                streamErrorCountRef.current++;

                if (streamStatus !== 'error') {
                    setStreamStatus('error');
                    addStatusMessage('error', 'Stream connection error');
                }

                // Close stream if too many errors
                if (streamErrorCountRef.current > 10) {
                    addStatusMessage('error', 'Too many stream errors, stopping stream');
                    stopStream();
                }
            };

            // Handle connection open
            source.onopen = () => {
                console.log('Stream connection opened');
                setStreamStatus('active');
                addStatusMessage('success', 'Browser stream connected');
                streamErrorCountRef.current = 0;
            };

            setStreaming(true);
        } catch (error) {
            console.error('Error initializing stream:', error);
            addStatusMessage('error', `Stream error: ${error.message}`);
            setStreamStatus('error');
        }
    };

    // Stop the browser stream with improved cleanup
    const stopStream = () => {
        // Clean up any pending timeouts
        if (sourceTimeoutsRef.current && sourceTimeoutsRef.current.length > 0) {
            console.log(`Clearing ${sourceTimeoutsRef.current.length} pending timeouts`);
            sourceTimeoutsRef.current.forEach(timeout => clearTimeout(timeout));
            sourceTimeoutsRef.current = [];
        }

        // Close EventSource connection
        if (streamSourceRef.current) {
            try {
                console.log('Closing stream connection...');

                // Notify the server we're disconnecting using direct API call
                try {
                    axios.post(`${SERVER_URL}/stream-disconnect`, {
                        sessionId: sessionId,
                        timestamp: Date.now()
                    }).catch(err => {
                        console.warn('Failed to notify server about disconnect:', err);
                    });
                } catch (notifyError) {
                    console.warn('Failed to notify server about disconnect:', notifyError);
                }

                // Properly close the EventSource
                streamSourceRef.current.close();

                // Remove all event listeners to prevent memory leaks
                const source = streamSourceRef.current;
                source.onmessage = null;
                source.onerror = null;
                source.onopen = null;

                // Remove any custom event listeners
                try {
                    source.removeEventListener('status', () => { });
                } catch (e) {
                    // Ignore errors from removing event listeners
                }

                // Clear reference
                streamSourceRef.current = null;

                // Update state
                setStreaming(false);
                setStreamStatus('inactive');
                addStatusMessage('info', 'Stream connection closed');
            } catch (error) {
                console.error('Error closing stream:', error);
                // Still clean up even if there was an error
                streamSourceRef.current = null;
                setStreaming(false);
                setStreamStatus('error');
            }
        } else {
            // No active stream, just update state
            setStreaming(false);
            setStreamStatus('inactive');
        }

        // Reset error counters
        streamErrorCountRef.current = 0;
    };

    return (
        <div className="app-container">
            <header className="app-header">
                <h1>OpenAI MCP Client</h1>
                <button
                    className="toggle-preview-button"
                    onClick={togglePreview}
                >
                    {previewVisible ? 'Hide Preview' : 'Show Preview'}
                </button>
            </header>

            <main className="main-content">
                <div className="chat-section">
                    <div className="chat-header">
                        <h2>Chat</h2>
                        <button
                            className="toggle-technical-button"
                            onClick={toggleTechnicalMessages}
                            title={showTechnicalMessages ? 'Hide technical details' : 'Show technical details'}
                        >
                            {showTechnicalMessages ? 'Hide Technical Details' : 'Show Technical Details'}
                        </button>
                    </div>
                    <div className="chat-container">
                        {messages
                            .filter(msg =>
                                ['user', 'assistant'].includes(msg.role) ||
                                (showTechnicalMessages && ['tool', 'system', 'function'].includes(msg.role))
                            )
                            .map((message, index) => (
                                <div key={index} className={`message ${message.role}`}>
                                    <div className="message-role">{message.role === 'function' ? 'tool-result' : message.role}</div>
                                    <div className="message-content">
                                        {message.role === 'function' || message.role === 'tool' ? (
                                            <pre className="tool-content">{typeof message.content === 'string' ? message.content : JSON.stringify(message.content, null, 2)}</pre>
                                        ) : (
                                            <div>{message.content}</div>
                                        )}
                                        {message.tool_calls && (
                                            <div className="tool-calls">
                                                <div className="tool-call-header">Tool Calls:</div>
                                                {message.tool_calls.map((tool, toolIndex) => (
                                                    <div key={toolIndex} className="tool-call">
                                                        <div className="tool-name">{tool.function?.name || 'Unknown Tool'}</div>
                                                        <pre className="tool-args">{tool.function?.arguments || '{}'}</pre>
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ))}
                        {error && (
                            <div className="message error">
                                <div className="message-role">Error</div>
                                <div className="message-content">{error}</div>
                            </div>
                        )}
                        {loading && (
                            <div className="message loading">
                                <div className="message-content">
                                    <div className="loading-spinner"></div>
                                </div>
                            </div>
                        )}
                        <div ref={messagesEndRef} />
                    </div>

                    <form className="input-container" onSubmit={handleSendMessage}>
                        <input
                            type="text"
                            value={inputValue}
                            onChange={(e) => setInputValue(e.target.value)}
                            placeholder="Type your message..."
                            className="message-input"
                            disabled={loading || !sessionId}
                        />
                        <button
                            type="submit"
                            className="send-button"
                            disabled={loading || !sessionId || !inputValue.trim()}
                        >
                            Send
                        </button>
                    </form>
                </div>

                {previewVisible && (
                    <div className="preview-section">
                        <h2 className="preview-title">
                            Browser Preview
                            <div className="preview-controls">
                                {streaming ? (
                                    <button
                                        onClick={stopStream}
                                        className="stream-button stop"
                                        disabled={!sessionId}
                                    >
                                        Stop Stream
                                    </button>
                                ) : (
                                    <button
                                        onClick={startStream}
                                        className="stream-button start"
                                        disabled={!sessionId}
                                    >
                                        Start Stream
                                    </button>
                                )}
                                <button
                                    onClick={requestScreenshot}
                                    className="refresh-preview-button"
                                    disabled={!sessionId || streaming}
                                >
                                    Take Screenshot
                                </button>
                            </div>
                        </h2>
                        <div className={`stream-status ${streamStatus} ${streaming ? 'pulsing' : ''}`}>
                            {streamStatus === 'waiting' ? 'Test starting...' :
                                streamStatus === 'connecting' ? 'Connecting...' :
                                    streamStatus === 'connected' ? 'Test running' :
                                        streamStatus.charAt(0).toUpperCase() + streamStatus.slice(1)}
                        </div>
                        <div className="browser-preview">
                            {browserImage ? (
                                <img
                                    src={browserImage}
                                    alt="Browser preview"
                                    className="browser-image"
                                    title={streaming ? "Live stream" : "Static screenshot"}
                                />
                            ) : (
                                <div className="no-preview">
                                    No browser activity yet
                                </div>
                            )}
                        </div>

                        {/* Add status log section below the preview */}
                        <div className="status-log">
                            <h3>Status Log</h3>
                            <div className="status-messages">
                                {statusMessages.length === 0 ? (
                                    <div className="status-message info">
                                        <span className="status-time">--:--:--</span>
                                        <span className="status-text">Waiting for activity...</span>
                                    </div>
                                ) : (
                                    statusMessages.map((status, index) => (
                                        <div key={index} className={`status-message ${status.type}`}>
                                            <span className="status-time">{status.time}</span>
                                            <span className="status-text">{status.text}</span>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>
                    </div>
                )}
            </main>
        </div>
    );
}

export default App;
